import ast, hashlib, importlib.util, json
from pathlib import Path
r=json.load(open('/tmp/runtime_contract.json'))
for name in ['candidate.py','control_coordinates.py','control_replicas.py']:
 s=Path('/workspace',name).read_text(); tree=ast.parse(s); compile(tree,name,'exec')
 config=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
 fn=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in fn.args.args][-len(fn.args.defaults):],fn.args.defaults))
 for k,v in config.items():
  expected=ast.literal_eval(defaults[k]); assert list(expected)==v if isinstance(v,list) else expected==v
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(i.name.split('.')[0] in ('torch','math') for i in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in ('torch','unirank')
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in ('open','exec','eval','__import__')
 print(name,'syntax/import/CONFIG checks passed',hashlib.sha256(s.encode()).hexdigest())
base=Path('/workspace/candidate.py').read_text()
for name,mode in [('control_coordinates.py','coordinates'),('control_replicas.py','replicas')]:
 normalized=Path('/workspace',name).read_text().replace(\"'representation_mode': '\"+mode+\"'\",\"'representation_mode': 'fields'\").replace(\"representation_mode='\"+mode+\"'\",\"representation_mode='fields'\")
 assert normalized==base
print('All source differences limited to CONFIG and constructor mode defaults.')
# Execute only the actual fixed-selection AST with a tiny standard-library
# matrix shim. This checks partition combinatorics, not PyTorch model behavior.
class Matrix:
 def __init__(self,n,m): self.data=[[0.0]*m for _ in range(n)]
 def __setitem__(self,key,value):
  i,j=key
  if isinstance(j,slice):
   for k in range(*j.indices(len(self.data[i]))): self.data[i][k]=value
  else: self.data[i][j]=value
 def fill_(self,value):
  for row in self.data:
   for i in range(len(row)): row[i]=value
class Torch:
 @staticmethod
 def zeros(n,m): return Matrix(n,m)
import math
class State: group_count=7; value_width=112
init=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
select=next(n for n in init.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='selection' for t in n.targets))
branch=next(n for n in init.body if isinstance(n,ast.If) and isinstance(n.test,ast.Compare) and isinstance(n.test.left,ast.Name) and n.test.left.id=='representation_mode')
for mode in ['fields','coordinates','replicas']:
 env={'self':State(),'torch':Torch,'representation_mode':mode,'embedding_dim':16,'range':range,'math':math}
 exec(compile(ast.Module(body=[select,branch],type_ignores=[]),'<selection-check>','exec'),env)
 a=env['selection'].data
 assert all(abs(sum(row[j]**2 for row in a)-1)<1e-12 for j in range(112))
 if mode"'!='"'replicas':
  assert all(sum(row)==16 for row in a)
  assert all(sum(row[j] for row in a)==1 for j in range(112))
 if mode=='fields': assert all(a[i][j]==float(j//16==i) for i in range(7) for j in range(112))
 if mode=='coordinates': assert all(a[i][j]==float(j%7==i) for i in range(7) for j in range(112))
 print(mode,'actual selection-branch partition/norm invariants passed')
print('torch available:',importlib.util.find_spec('torch') is not None)
for h in r['context']['history']:
 path=Path('/workspace','history_'+h['id'].replace('-','_')+'.py')
 if path.exists(): assert hashlib.sha256(path.read_bytes()).hexdigest()==h['source_sha256']
